async function boot(){try{const session=await api('/api/session');state.loginMethod=session.login_method||'token';acceptSession(session);state.loading=state.authenticated;render();if(state.authenticated)await refresh({projects:true});}catch(error){state.loading=false;state.error=error.message;render();}if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{/* Optional offline shell; live requests remain usable. */});}}
